import{createBrandCanvas}from'./studio-brand.js?v=1';
import{createPromptHintHook}from'./mopix-prompt-hints.js?v=2';
const PHRASES=['Ý tưởng đang chuyển động…','Một chút kiên nhẫn cho điều mới…','Mỗi ý tưởng đều có nhịp riêng…','Cảm hứng vẫn đang ở đây…','Dành thêm một nhịp cho sáng tạo…','Chờ một chút, cùng giữ dòng cảm hứng…','Một khoảng lặng cho ý tưởng…','Điều mới cần một chút thời gian…','Cứ để trí tưởng tượng tiếp tục…','Ý tưởng của bạn đang được xử lý…','Trong lúc chờ, nghĩ thêm một góc nhìn…','Sáng tạo theo nhịp của bạn…'];
export function createLiquidLoader(React){const{createElement:h,useRef:R,useEffect:E}=React,Brand=createBrandCanvas(React),useHint=createPromptHintHook(React);function Busy({compact=false}){const canvas=R(null),text=useHint(false,PHRASES,true);E(()=>{const el=canvas.current,ctx=el.getContext('2d'),size=compact?48:152,dpr=Math.min(devicePixelRatio||1,2);el.width=size*dpr;el.height=size*dpr;ctx.scale(dpr,dpr);let frame=0,last=0;const reduced=matchMedia('(prefers-reduced-motion: reduce)');function draw(now){if(now-last<30&&!reduced.matches){frame=requestAnimationFrame(draw);return}last=now;ctx.clearRect(0,0,size,size);const n=compact?7:13,gap=size/(n+1),t=reduced.matches?0:now/1100;for(let y=0;y<n;y++)for(let x=0;x<n;x++){const wave=(Math.sin(x*.48+y*.38-t*2.1)+Math.cos(Math.hypot(x-n*.5,y-n*.5)*.65-t*1.5)+2)/4;ctx.fillStyle=`rgba(208,214,224,${.08+wave*.52})`;ctx.beginPath();ctx.arc((x+1)*gap,(y+1)*gap,.45+wave*(compact?1.3:2),0,Math.PI*2);ctx.fill()}if(!reduced.matches&&!document.hidden)frame=requestAnimationFrame(draw)}const visibility=()=>{cancelAnimationFrame(frame);if(!document.hidden)frame=requestAnimationFrame(draw)};frame=requestAnimationFrame(draw);document.addEventListener('visibilitychange',visibility);return()=>{cancelAnimationFrame(frame);document.removeEventListener('visibilitychange',visibility)}},[compact]);return h('div',{className:'mopix-busy-state'+(compact?' is-compact':''),role:'status','aria-label':'Đang xử lý'},h('canvas',{ref:canvas,'aria-hidden':true}),h('span',{className:'mopix-busy-caption','aria-hidden':true},text))}return function Loader(props){return props.brand||props.home?h(Brand,props):h(Busy,props)}}
